import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import axios from "axios";
import * as ENV from "../config";

const initialState = {
  user: JSON.parse(localStorage.getItem("loggedUser")) || null,
  role: localStorage.getItem("role") || null,
  isLoading: false,
  isSuccess: false,
  isError: false,
};

// Register
export const registerUser = createAsyncThunk(
  "users/registerUser",
  async (data, thunkAPI) => {
    try {
      const res = await axios.post(`${ENV.SERVER_URL}/registerUser`, data);
      return res.data.user;
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response?.data || "Error");
    }
  }
);

// Login
export const login = createAsyncThunk("users/login", async (data, thunkAPI) => {
  try {
    const res = await axios.post(`${ENV.SERVER_URL}/login`, data);
    return res.data; // contains user + role
  } catch (err) {
    return thunkAPI.rejectWithValue(err.response?.data || "Login failed");
  }
});

// Fetch single user
export const fetchUser = createAsyncThunk(
  "users/fetchUser",
  async (email, thunkAPI) => {
    try {
      const res = await axios.get(`${ENV.SERVER_URL}/user/${email}`);
      return res.data;
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response?.data || "Fetch failed");
    }
  }
);

// Logout
export const logout = createAsyncThunk("users/logout", async () => {
  localStorage.removeItem("loggedUser");
  localStorage.removeItem("role");
  return true;
});

const userSlice = createSlice({
  name: "users",
  initialState,
  reducers: {
    restoreUser: (state) => {
      const saved = JSON.parse(localStorage.getItem("loggedUser"));
      const role = localStorage.getItem("role");
      state.user = saved || null;
      state.role = role || null;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(registerUser.fulfilled, (state, action) => {
        state.user = action.payload;
        state.isSuccess = true;
      })
      .addCase(login.fulfilled, (state, action) => {
        state.user = action.payload.user;
        state.role = action.payload.role;
        state.isSuccess = true;
      })
      .addCase(fetchUser.fulfilled, (state, action) => {
        state.user = { ...state.user, ...action.payload };
      })
      .addCase(logout.fulfilled, (state) => {
        state.user = null;
        state.role = null;
        state.isSuccess = false;
      });
  },
});

export const { restoreUser } = userSlice.actions;
export default userSlice.reducer;
